List<String> orderAll(List<String> loaves) throws Exception {
    try (ExecutorService pool = Executors.newFixedThreadPool(8)) {          // 1. 8 threads = at most 8 calls
        CompletionService<String> done = new ExecutorCompletionService<>(pool);
        for (String loaf : loaves) done.submit(() -> bakery.order(loaf));     // 2. every task queued up front
        List<String> tickets = new ArrayList<>();
        for (int i = 0; i < loaves.size(); i++) tickets.add(done.take().get());   // 3. fan-in, in finish order
        return tickets;
    }   // a failure surfaces at get(); the other tasks keep running until close() waits for them
}

