suspend fun orderAll(loaves: List<String>): List<String> = coroutineScope {
    val hatch = produce { loaves.forEach { send(it) } }                 // 2. handed out one at a time
    val tickets = Channel<String>()
    val team = List(8) { launch { for (loaf in hatch) tickets.send(bakery.order(loaf)) } }   // 1. 8 helpers
    launch { team.joinAll(); tickets.close() }
    val result = mutableListOf<String>()
    for (t in tickets) result += t                                      // 3. fan-in, in finish order
    result
}   // a failure cancels the producer and every helper, then rethrows

