@OptIn(ExperimentalCoroutinesApi::class)
suspend fun washAll(pans: List<String>) = coroutineScope {
    val pile = produce { for (pan in pans) send(pan) }   // closed when the block ends
    repeat(3) {
        launch { for (pan in pile) wash(pan) }           // each pan goes to one helper
