// Java equivalent: a pool of 3 threads, and invokeAll to wait for every task
void washAll(List<String> pans) throws Exception {
    try (ExecutorService sinks = Executors.newFixedThreadPool(3)) {
        List<Callable<Void>> tasks = pans.stream()
            .<Callable<Void>>map(pan -> () -> { wash(pan); return null; })
            .toList();
        for (Future<Void> f : sinks.invokeAll(tasks)) f.get();   // rethrows the first failure
    }   // unlike coroutineScope, the other washes are not cancelled on a failure
}

